### 3. Reverse Proxy Forwarder (ApiGateway.ReverseProxy)

```csharp
// ProxyMiddleware.cs
public class ProxyMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ProxyMiddleware> _logger;
    private readonly IServiceProvider _serviceProvider;

    public ProxyMiddleware(
        RequestDelegate next,
        ILogger<ProxyMiddleware> logger,
        IServiceProvider serviceProvider)
    {
        _next = next;
        _logger = logger;
        _serviceProvider = serviceProvider;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var routeData = context.GetRouteData();
        var serviceName = routeData?.Values["service"] as string;

        if (string.IsNullOrEmpty(serviceName))
        {
            await _next(context);
            return;
        }

        var routeConfig = _serviceProvider.GetRequiredService<IConfiguration>()
            .GetSection($"Services:{serviceName}")
            .Get<RouteConfiguration>();

        if (routeConfig == null)
        {
            context.Response.StatusCode = 404;
            return;
        }

        // Forward request to downstream service
        var proxyClient = new HttpClient();
        var request = new HttpRequestMessage();

        // Copy headers (except those we don't want to forward)
        foreach (var header in context.Request.Headers)
        {
            if (!header.Key.StartsWith("Authorization") &&
                !header.Key.StartsWith("Cookie"))
            {
                request.Headers.TryAddWithoutValidation(header.Key, header.Value.ToArray());
            }
        }

        // Forward the request body
        using var memoryStream = new MemoryStream();
        await context.Request.Body.CopyToAsync(memoryStream);
        memoryStream.Position = 0;
        request.Content = new StreamContent(memoryStream);
        request.Content.Headers.ContentType = context.Request.ContentType;

        // Set the target URL
        var targetUrl = new Uri($"{routeConfig.ServiceUrl}{context.Request.Path}");

        request.Method = context.Request.Method;
        request.RequestUri = targetUrl;

        // Forward the request
        var response = await proxyClient.SendAsync(request);

        // Copy response back to client
        foreach (var header in response.Headers)
        {
            context.Response.Headers[header.Key] = header.Value.ToArray();
        }

        await response.Content.CopyToAsync(context.Response.Body);
    }
}
```

### 4. JWT Authentication and Authorization (ApiGateway.Auth)

```csharp
// JwtAuthenticationMiddleware.cs
public class JwtAuthenticationMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<JwtAuthenticationMiddleware> _logger;
    private readonly IConfiguration _configuration;
    private readonly IServiceProvider _serviceProvider;

    public JwtAuthenticationMiddleware(
        RequestDelegate next,
        ILogger<JwtAuthenticationMiddleware> logger,
        IConfiguration configuration,
        IServiceProvider serviceProvider)
    {
        _next = next;
        _logger = logger;
        _configuration = configuration;
        _serviceProvider = serviceProvider;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var token = context.Request.Headers["Authorization"].FirstOrDefault()?.Split(" ").Last();

        if (string.IsNullOrEmpty(token))
        {
            context.Response.StatusCode = 401;
            return;
        }

        try
        {
            var jwtSettings = _configuration.GetSection("JwtSettings").Get<JwtSettings>();
            var tokenHandler = new JwtSecurityTokenHandler();
            var validationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                ValidIssuer = jwtSettings.Issuer,
                ValidAudience = jwtSettings.Audience,
                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtSettings.SecretKey))
            };

            var principal = tokenHandler.ValidateToken(token, validationParameters, out _);
            var claims = principal.Claims.Select(c => new Claim(c.Type, c.Value)).ToList();

            var jwtClaims = new JwtClaims(
                Subject: claims.FirstOrDefault(c => c.Type == "sub")?.Value ?? string.Empty,
                Roles: claims.Where(c => c.Type == "role").Select(c => c.Value),
                Scopes: claims.Where(c => c.Type == "scope").Select(c => c.Value),
                Expiration: DateTime.Parse(claims.FirstOrDefault(c => c.Type == "exp")?.Value ?? string.Empty),
                Issuer: jwtSettings.Issuer,
                Audience: jwtSettings.Audience
            );

            // Store claims in HttpContext for later use
            context.Items["JwtClaims"] = jwtClaims;

            // Check authorization based on route configuration
            var routeData = context.GetRouteData();
            var serviceName = routeData?.Values["service"] as string;

            if (!string.IsNullOrEmpty(serviceName))
            {
                var routeConfig = _configuration.GetSection($"Services:{serviceName}").Get<RouteConfiguration>();

                if (routeConfig.AllowedRoles != null &&
                    routeConfig.AllowedRoles.Length > 0 &&
                    !routeConfig.AllowedRoles.Any(r => jwtClaims.Roles.Contains(r)))
                {
                    context.Response.StatusCode = 403;
                    return;
                }

                if (routeConfig.AllowedScopes != null &&
                    routeConfig.AllowedScopes.Length > 0 &&
                    !routeConfig.AllowedScopes.Any(s => jwtClaims.Scopes.Contains(s)))
                {
                    context.Response.StatusCode = 403;
                    return;
                }
            }

            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "JWT validation failed");
            context.Response.StatusCode = 401;
        }
    }
}
```

### 5. Distributed Tracing Middleware (ApiGateway.Tracing)

```csharp
// TracingMiddleware.cs
public class TracingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<TracingMiddleware> _logger;

    public TracingMiddleware(RequestDelegate next, ILogger<TracingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Generate or extract correlation ID
        var correlationId = context.Request.Headers["X-Correlation-ID"].FirstOrDefault() ??
                           Guid.NewGuid().ToString();

        // Store correlation ID in context
        context.Items["CorrelationId"] = correlationId;

        // Add to request headers
        context.Request.Headers["X-Correlation-ID"] = correlationId;

        // Log the start of the request with correlation ID
        _logger.LogInformation("Request started - Correlation ID: {CorrelationId}", correlationId);

        try
        {
            await _next(context);
        }
        finally
        {
            // Log the end of the request with correlation ID
            _logger.LogInformation("Request completed - Correlation ID: {CorrelationId}", correlationId);
        }
    }
}
```

### 6. Main Web Host (ApiGateway.Web)

```csharp
// Program.cs
var builder = WebApplication.CreateBuilder(args);

// Add services to the container
builder.Services.AddControllers();

// Add reverse proxy services
builder.Services.AddReverseProxy()
    .LoadFromConfig(builder.Configuration.GetSection("ReverseProxy"));

// Add JWT authentication
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,
            ValidIssuer = builder.Configuration["JwtSettings:Issuer"],
            ValidAudience = builder.Configuration["JwtSettings:Audience"],
            IssuerSigningKey = new SymmetricSecurityKey(
                Encoding.UTF8.GetBytes(builder.Configuration["JwtSettings:SecretKey"]))
        };
    });

// Add distributed tracing
builder.Services.AddSingleton<IHttpContextAccessor, HttpContextAccessor>();

// Add custom middleware
builder.Services.AddTransient<TracingMiddleware>();
builder.Services.AddTransient<JwtAuthenticationMiddleware>();

var app = builder.Build();

// Configure the HTTP request pipeline
app.UseRouting();

// Add distributed tracing middleware
app.UseMiddleware<TracingMiddleware>();

// Add JWT authentication middleware
app.UseAuthentication();
app.UseAuthorization();

// Add reverse proxy middleware
app.UseReverseProxy();

// Add custom JWT auth middleware (for more complex scenarios)
app.UseMiddleware<JwtAuthenticationMiddleware>();

// Map controllers
app.MapControllers();

app.Run();
```

